contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address target, bytes memory data) public payable {
        require(caller != c.Owner(), "caller must not be owner");
        require(address(this) != c.Owner(), "test contract must not be owner");
        require(address(c).balance > 0, "contract needs balance");

        uint256 beforeBal = address(c).balance;

        bool reverted;
        uint256 sentValue = 0;
        (bool ok, ) = address(this).call(
            abi.encodeWithSignature("nonOwnerCommand(address,address,bytes,uint256)", caller, target, data, sentValue)
        );
        require(ok, "internal call failed");

        (bool success, bool wasReverted) = address(this).staticcall(
            abi.encodeWithSignature("getCommandResult()")
        );
        require(success, "result call failed");
        reverted = wasReverted;

        uint256 afterBal = address(c).balance;

        assert(reverted || afterBal == beforeBal);
    }

    bool private lastCommandReverted;

    function nonOwnerCommand(address caller, address target, bytes memory data, uint256 sentValue) external payable {
        require(msg.sender == address(this), "only self");
        bool r;
        try c.Command{value: sentValue}(target, data) {} catch {
            r = true;
        }
        lastCommandReverted = r;
    }

    function getCommandResult() external view returns (bool) {
        require(msg.sender == address(this), "only self");
        return lastCommandReverted;
    }

    receive() external payable {}
}

